import { RoomGame } from '../room-game.enum';

export default interface RoomJoinRequest {
    playerName: string;
    roomName: string;
    /** The game of the page: a room of another game is refused */
    game: RoomGame;
    /** The password of a private room, ignored by a public one */
    password?: string;
    /**
     * A secret of the player, generated by its page: the API keeps its hash once the player joined the room, and lets it
     * join a private room again without its password
     */
    token: string;
}
